function vMatch(name,rows){const K=VKIT[name]||[];let cost=0,full=0;const miss=[],short=[];rows.forEach(r=>{const k=K.find(x=>x[0].test(r.l));if(!k){miss.push(r.l);return;}const q=Math.min(k[1],r.q);cost+=q*k[2];if(k[1]>=r.q)full++;else short.push(`${r.l} ${k[1]} из ${r.q}`);});return {full,part:short.length,miss,short,cost,n:rows.length};}
