(()=>{const d=EVENTS.find(x=>x.id==='demo'),s=EVENTS.find(x=>x.id==='sale');if(d){d.codes=[{id:uid(),code:'JAZZ15',pct:15,limit:30}];const a=d.people.find(p=>p.group==='artist'&&p.rider);const P3=n=>d.prod.find(x=>x.n===n),row=(l,q,cat)=>({id:uid(),k:'',l,q,cat});P3('Звук').rows.push(row('Порталы и сабы на 350 гостей',1,'Звук'),row('Пульт FOH',1,'Звук'),row('Радиомикрофон для ведущего',2,'Звук'));P3('Свет').rows.push(row('Световые головы',8,'Свет'),row('Стробоскоп',2,'Свет'),row('Дым-машина',1,'Свет'),row('Световой пульт',1,'Свет'));P3('Свет').note='Свет на обе сцены, оператор с 17:00';P3('Декор').rows.push(row('Бэкдроп с логотипом Digital Jazz',1,'Декорации'),row('Неоновая вывеска',1,'Декорации'));d.prod.push({id:uid(),n:'Видео',cat:'',rows:[row('LED-экран за сценой 4×2 м',1,''),row('Медиасервер',1,'')],note:'',prov:'',custom:true});}
 if(s)s.codes=[{id:uid(),code:'EARLY10',pct:10,limit:50},{id:uid(),code:'FRIENDS',pct:20,limit:20}];})();
EVENTS.forEach(ev=>ev.people.forEach(norm));let E=EVENTS[2];

/* ---------------- расчёты ---------------- */
const venue=()=>E.people.find(p=>p.group==='venue');
const cap=()=>venue()?.cap||0;
const list=g=>E.people.filter(p=>p.group===g);
const waiting=()=>E.people.filter(p=>p.stage===0);
const shortlist=()=>E.people.filter(p=>p.stage===-1);
const cost=()=>{const deals=E.people.reduce((a,p)=>a+p.fee,0),other=E.costs.reduce((a,c)=>a+c.a,0)+promoBudget(),base=deals+other;return {deals,other,base,reserve:base*E.reserve,total:base*(1+E.reserve)};};
const promoBudget=()=>(E.channels||[]).reduce((a,c)=>a+c.budget,0);
const soldTotal=()=>(E.sales||[]).reduce((a,x)=>a+x,0);
const phase=()=>!E.announce||TODAY<E.announce?0:!E.date||TODAY<E.date?2:4;
const overdue=p=>p.st!=='out'&&p.d<TODAY;
/* сводная потребность: на одной сцене сеты идут подряд — одинаковая позиция считается по максимуму, не суммой */
const provFor=cat=>E.people.find(p=>p.group==='vendor'&&p.role===cat);
function autoProv(row){if(!row.cat)return '';const d=DICT.find(x=>x[0]===row.k),v=venue();if(d&&d[3]==='Площадка')return v?.name||'';if(d&&provFor(d[3]))return provFor(d[3]).name;return provFor(CAT_ROLE[row.cat])?.name||'';}
function needs(){const map=new Map();list('artist').filter(p=>p.rider).forEach(p=>{const sc=sceneOf(p.scene);p.rider.rows.forEach(r=>{const l=(r.l||'').trim();if(!l||!r.q)return;const key=r.k||'x-'+l.toLowerCase().replace(/[^a-zа-яё0-9]+/gi,'-');const o=map.get(key)||{key,label:l,cat:r.cat,qty:0,src:[],by:{},pov:'',row:r};o.by[sc.n]=Math.max(o.by[sc.n]||0,r.q);if(!o.src.includes(p.name))o.src.push(p.name);const po=(p.rider.prov||{})[r.cat];if(po&&!o.pov)o.pov=po;map.set(key,o);});});
 (E.prod||[]).forEach(d=>d.rows.forEach(r=>{const l=(r.l||'').trim();if(!l||!r.q)return;const key='p-'+d.id+'-'+l.toLowerCase().replace(/[^a-zа-яё0-9]+/gi,'-');const o=map.get(key)||{key,label:l,cat:d.n,qty:0,src:[],by:{},pov:d.prov,row:{...r,cat:d.cat},prod:d};o.by['Событие']=(o.by['Событие']||0)+r.q;const sl='райдер «'+(d.n||'свой')+'»';if(!o.src.includes(sl))o.src.push(sl);map.set(key,o);}));
 map.forEach(o=>{o.qty=Object.values(o.by).reduce((a,x)=>a+x,0);});
 const v=venue(),kit=v&&VENUE_KIT[v.name]||{};
 return [...map.values()].map(n=>{const ov=(E.reqOver||{})[n.key]||{};const qty=ov.qty??n.qty;const d=DICT.find(x=>x[0]===n.key);const fromVenue=Math.min(qty,kit[n.key]||0);
  let prov=ov.prov||n.pov;if(!prov)prov=d&&d[3]==='Площадка'&&v?v.name:fromVenue>=qty&&v?v.name:autoProv(n.row);return {...n,qty,fromVenue:prov===v?.name?qty:fromVenue,prov};});}
function hospNeeds(){const out=[];list('artist').filter(p=>p.rider).forEach(p=>p.rider.h.filter(x=>x.trim()).forEach(line=>{const h=HOSP.find(x=>x[0].test(line));const cat=h?h[1]:'Площадка';const prov=cat==='Площадка'?venue()?.name||'':provFor(cat)?.name||'';out.push({line,who:p.name,cat,prov});}));return out;}
function reqs(){const N=needs(),H=hospNeeds(),v=venue();const provs=[...(v?[v]:[]),...list('vendor')];
 return provs.map(p=>{const tech=N.filter(n=>n.prov===p.name||(p===v&&n.fromVenue&&n.prov!==p.name));const hosp=H.filter(h=>h.prov===p.name);const base=p.group==='venue'?'Техпаспорт площадки, электричество, гримёрные, график монтажа':BASE_REQ[p.role]||'';
  return {name:p.name,role:p.role,p,tech,hosp,base,st:(E.reqSt||{})[p.name]||'draft'};}).filter(r=>r.tech.length||r.hosp.length||r.base);}
const REQ_ST={draft:['Не отправлен',''],sent:['Ждём ответ','wait'],ok:['Подтверждено','ok'],change:['Нужна замена','od']};
const paidSum=()=>E.people.reduce((a,p)=>a+p.paid,0);
const income=all=>E.incomes.filter(i=>all||i.ok).reduce((a,i)=>a+i.a,0);
const tixQty=()=>(E.tickets||[]).reduce((a,t)=>a+(t.qty||0),0);
function fW(){return (E.tickets||[]).filter(t=>t.qty>0).reduce((a,t)=>a+t.qty*(t.k||1),0)||cap();}
function fBase(){const F=E.formula,w=fW();if(!w)return 0;return Math.max(0,cost().total-income(false))*(1+(F.margin||0)/100)/(w*(F.fill||100)/100);}
const tPrice=t=>E.formula&&E.formula.on?Math.ceil(fBase()*(t.k||1)/100)*100:(t.price||0);
function rawAvg(){const T=(E.tickets||[]).filter(t=>t.qty>0&&tPrice(t)>0),q=T.reduce((a,t)=>a+t.qty,0);if(!q){const p=(E.tickets||[]).map(tPrice).filter(Boolean);return p.length?Math.min(...p):0;}return T.reduce((a,t)=>a+t.qty*tPrice(t),0)/q;}
const codeUse=c=>c.limit||Math.round((tixQty()||cap())*.1);
const discLoss=()=>{const r=rawAvg();return (E.codes||[]).reduce((a,c)=>a+codeUse(c)*r*(c.pct||0)/100,0);};
function avgPrice(){if(!E.tickets)return 0;const r=rawAvg(),q=tixQty()||cap();return r?Math.max(0,Math.round(r-(q?discLoss()/q:0))):0;}
const minPrice=()=>{const p=(E.tickets||[]).map(tPrice).filter(Boolean);return p.length?Math.min(...p):0;};
function soldBy(){let s=soldTotal();return E.tickets.map(t=>{const x=Math.min(t.qty||0,s);s-=x;return x;});}
const breakEven=all=>E.price?Math.ceil(Math.max(0,cost().total-income(all))/E.price):null;
const tkey=t=>(t<'06:00'?'2':'1')+t;
const sceneOf=id=>(E.scenes||[]).find(s=>s.id===id)||(E.scenes||[])[0]||{id:'main',n:'Сцена'};
const setEnd=p=>addMin(p.set,p.len||45);
const sets=sc=>list('artist').filter(p=>p.set&&(!sc||sceneOf(p.scene).id===sc)).sort((a,b)=>tkey(a.set).localeCompare(tkey(b.set)));
/* пересечения сетов внутри одной сцены */
function clashes(){const out=[];(E.scenes||[]).forEach(sc=>{const L=sets(sc.id);for(let i=1;i<L.length;i++)if(tkey(L[i].set)<tkey(setEnd(L[i-1])))out.push([L[i-1],L[i],sc]);});return out;}
